  function renderEvidence() {
    const list = articles.filter(
      (a) =>
        (!query ||
          `${a.evidence}${workspace.withdrawn && a.id === controlledDocument ? "来源已撤回 · 内容不可用" : a.title}`.includes(
            query,
          )) &&
        (filter === "全部" ||
          (filter === "已撤回"
            ? workspace.withdrawn && a.id === controlledDocument
            : !workspace.withdrawn || a.id !== controlledDocument)),
    );
    const showWithdrawn =
      filter !== "有效" &&
      (!query || "EVD-20261031-009 已撤回记录".includes(query));
    return (
      <>
        <PageHeader
          title="证据中心"
          description="连接原始资料、结构化事实与研判结论，保留可审计的证据链。"
        >
          <Badge tone="green" dot>
            引用链路完整
          </Badge>
        </PageHeader>
        <div className="notice">
          <Shield size={18} />
          <p>
            证据状态变化将影响下游引用。永久撤回的原始内容不再展示，仅保留审计标记与失效原因。
          </p>
        </div>
        <Panel title="证据台账" action={segments(["全部", "有效", "已撤回"])}>
          <div className="filter-bar">
            <SearchField
              value={query}
              onChange={setQuery}
              placeholder="搜索证据编号或标题"
            />
            <span className="filter-hint">规范化版本 v1 · 原始记录可追溯</span>
          </div>
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th>证据编号 / 原始内容</th>
                  <th>来源类型</th>
                  <th>规范化版本</th>
                  <th>状态</th>
                  <th>操作</th>
                </tr>
              </thead>
              <tbody>
                {list.map((a) => (
                  <tr key={a.id}>
                    <td className="article-cell">
                      <button
                        className="table-title"
                        onClick={() => open("evidence", a.id)}
                      >
                        {workspace.withdrawn && a.id === controlledDocument
                          ? "来源已撤回 · 原文不可读"
                          : a.title}
                      </button>
                      <small>{a.evidence}</small>
                    </td>
                    <td>{a.source}</td>
                    <td>
                      <code>
                        {workspace.withdrawn && a.id === controlledDocument
                          ? "v2 · source_withdrawn"
                          : "v1 · normalized"}
                      </code>
                    </td>
                    <td>
                      <Badge
                        tone={
                          workspace.withdrawn && a.id === controlledDocument
                            ? "orange"
                            : "green"
                        }
                        dot
                      >
                        {workspace.withdrawn && a.id === controlledDocument
                          ? "已撤回"
                          : "有效"}
                      </Badge>
                    </td>
                    <td>
                      <button
                        className="text-button"
                        onClick={() => open("evidence", a.id)}
                      >
                        追溯
                        <ArrowRight size={14} />
                      </button>
                    </td>
                  </tr>
                ))}
                {showWithdrawn && (
                  <tr>
                    <td className="article-cell">
                      <button
                        className="table-title muted"
                        onClick={() => open("evidence", "withdrawn")}
                      >
                        原始内容已撤回
                      </button>
                      <small>EVD-20261031-009</small>
                    </td>
                    <td>公开社区</td>
                    <td>
                      <code>v2 · invalidated</code>
                    </td>
                    <td>
                      <Badge tone="red">已撤回</Badge>
                    </td>
                    <td>
                      <button
                        className="text-button"
                        onClick={() => open("evidence", "withdrawn")}
                      >
                        查看状态
                        <ArrowRight size={14} />
                      </button>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
          {!list.length && !showWithdrawn && <EmptyState />}
        </Panel>
      </>
    );
  }
